from journal.engine.nudge import Nudge
from journal.support.timeout import Timeout


class WorkersNudges:
    BUILDER_ALIGNMENT = Nudge("workers", "builder_takes_the_next_task", "you are the builder: you handed work out {{limit}} times in a row with no code of your own between", "take the next task yourself, and hand one to a worker only when it is better done beside you", repeat=Timeout.tool_uses(50))
    ORCHESTRATOR_ALIGNMENT = Nudge("workers", "orchestrator_hands_the_work_out", "you are the orchestrator: you changed at least {{limit}} lines of code yourself since your last handover", "hand the work to a worker and review what comes back", repeat=Timeout.tool_uses(50))
    FITNESS_LOW = Nudge("workers", "work_mode_fitness_is_low", "your fitness as the {{mode}} is {{score}} of 100 over your last 50 tool uses: {{gaps}}", "bring the measures named back into their range", repeat=Timeout.tool_uses(50))
    SOLO_ALIGNMENT = Nudge("workers", "solo_researches_itself", "you are solo: you sent more subagents than you read and searched yourself", "read and research this yourself; a subagent is for the rare job too wide to do in your own turns", repeat=Timeout.tool_uses(50))
    READINESS = Nudge("workers", "clock_in_first", "your writes wait until you clock in", "journal task show <n>, then journal clock-in", repeat=Timeout.seconds(0))
    TEST_BUDGET_REFUSAL = Nudge("workers", "tests_go_through_a_turn", "you do not run {{command}} yourself: tests here run within a budget", "run them with journal tests turn", repeat=Timeout.seconds(0))
    TEST_HANDOVER = Nudge("workers", "tests_are_handed_over", "tests are handed over here, so you do not run {{command}}", "name the test that proves the point and the command that runs it in your proof; the agent that merges runs them", repeat=Timeout.seconds(0))
    OUTPUT_UNFINISHED = Nudge("workers", "own_output_running", "your output {{n}} still runs, and your run ends when you stop", "wait for it, then stop again", repeat=Timeout.seconds(0))
    OUTPUT_END = Nudge("workers", "own_output_ended", "output {{n}} ended with code {{status}}", "read it with journal output read {{n}} --summary", repeat=Timeout.seconds(0))
    USER_CLOSURE = Nudge("workers", "task_closed_by_user", "the user closed your task {{task}}", "stop now", repeat=Timeout.seconds(0))
    OPEN_TODOS = Nudge("workers", "open_todos", "your to-do list has {{count}} open items: {{items}}", "finish them, or say why with journal clock-out", repeat=Timeout.seconds(0))
    WORK_READY = Nudge("workers", "work_ready", "worker {{n}} ready: task {{task}}", repeat=Timeout.seconds(0))
    CHECK_REMINDER = Nudge("workers", "check_reminder", "worker {{n}} waits: task {{task}}", repeat=Timeout.seconds(180))
    RUN_UNFINISHED = Nudge("workers", "run_unfinished", "worker {{n}} ended without clocking out{{cause}}", repeat=Timeout.seconds(0))
    WORKER_REPORTED = Nudge("workers", "worker_reported", "worker {{n}} reported", repeat=Timeout.seconds(0))
    STARTED_PLANS = Nudge("workers", "started_plans", "started plans: {{plans}}", repeat=Timeout.minutes(10), blocks_regardless=True)
    PLAN_STALLED = Nudge("workers", "plan_stalled", "plan {{n}} stalled since {{since}}, {{minutes}} min", repeat=Timeout.minutes(525600))
    SUITE_BROKEN = Nudge("workers", "suite_failed_after_merges", "the whole suite failed in output {{run}} after the merges of {{workers}}", "read what failed, then send the work back to the worker whose change broke it: journal worker send {{n}} \"the whole suite fails since your merge: <what failed>; fix it and clock out again\"", repeat=Timeout.minutes(525600))
    DELIVERED_WAITING = Nudge("workers", "clocked_out_work_waits", "{{workers}} clocked out and their work waits for you", "check each point with journal worker check <n> <point>, or send one back with --short \"<what is missing>\", and merge what is checked with journal worker merge <n>", repeat=Timeout.seconds(0))
    ACTIVE_WORKERS = Nudge("workers", "wait_for_running_workers", "{{workers}} are still out and no work waits to be checked", "wait for them with journal worker wait {{numbers}}", repeat=Timeout.seconds(0))
    QUICK_REPORT = Nudge("workers", "quick_report_dropped_the_fitness", "worker {{n}} reported within a minute of its job's start while {{open}} tasks were open, which cost your fitness {{points}} points at once: queue it several tasks with journal worker queue {{n}} <task> <task>... --report queue, so it reports once for all of them", repeat=Timeout.seconds(0))
    WORKER_LIMITED = Nudge("workers", "worker_waits_for_the_usage_limit", "worker {{n}} stopped at the usage limit and goes on by itself at {{at}}", repeat=Timeout.seconds(0))
    ORCHESTRATE = Nudge("workers", "orchestrate", "{{count}} tasks are open; next: {{tasks}}", "dispatch a worker on each you can, journal worker dispatch \"<Name>\" --task <n>; block a task that waits and go on with the rest", repeat=Timeout.seconds(0))
    TASK_DELEGATION = Nudge("workers", "delegate_the_task", "{{name}} is in hand and you orchestrate; {{logged}}", "hand it to a worker with journal worker dispatch \"<Name>\" --task <n>, and review its report", repeat=Timeout.seconds(0))
    BLOCKED_CHECK = Nudge("workers", "check_blocked_tasks", "tasks {{tasks}} are paused or blocked", "resume a paused one you can go on with, unblock one whose wait has passed or that you can decide, and report what you decided", repeat=Timeout.seconds(300))
    CREW_REMINDER = Nudge("workers", "dispatch_while_busy", "{{count}} tasks open, no worker: {{tasks}}", repeat=Timeout.tool_uses(30))
    RELEASE_REFUSED = Nudge("workers", "release_waits_for_the_user", "{{line}} waits for the user: Orchestrator may release is off", "ask the user to release it, or to turn Orchestrator may release on", repeat=Timeout.seconds(0))
    IDLE_WORKER = Nudge("workers", "worker_has_no_work_left", "worker {{n}} has no work left", "queue it tasks with journal worker queue {{n}} <task> <task>, or retire it", repeat=Timeout.seconds(0))
    PLACE_FREE = Nudge("workers", "worker_place_free", "worker {{n}} free; open: {{tasks}}", repeat=Timeout.seconds(0))
    ORCHESTRATOR_MODE = Nudge("workers", "now_orchestrating", "orchestrating: dispatch tasks, review and merge, run the suite", repeat=Timeout.seconds(0))
    SOLO_MODE = Nudge("workers", "now_solo", "you now work solo", "do every job yourself: no worker is dispatched", repeat=Timeout.seconds(0))
    SOLO_DISPATCH = Nudge("workers", "no_workers_when_solo", "you work solo: no worker is dispatched", repeat=Timeout.seconds(0))
    CROWDED_RISING = Nudge("workers", "load_rising", "your load is {{rho}}: {{queue}} wait; clear {{first}} first, the oldest", repeat=Timeout.seconds(300))
    CROWDED_CRITICAL = Nudge("workers", "load_critical", "your load is {{rho}}, critical: {{queue}} wait, {{first}} the oldest", "ease it: turn the reviewer on, queue work with journal worker queue instead of dispatching, or lower workers.most_out", repeat=Timeout.seconds(300))
    PLACE_OPENED = Nudge("workers", "place_opened", "your load stayed at {{rho}} for {{minutes}} minutes: one place more, {{places}} workers out at once", repeat=Timeout.seconds(0))
    PLACE_CLOSED = Nudge("workers", "place_closed", "your load stayed at {{rho}} for {{minutes}} minutes: one place fewer, {{places}} workers out at once", repeat=Timeout.seconds(0))
    WAIT_MISSING = Nudge("workers", "task_names_another_without_a_wait", "task {{task}} names task {{other}}, still open, and does not wait on it", "journal task block {{task}} --on task:{{other}}", repeat=Timeout.seconds(0))
    WAIT_TEXT = Nudge("workers", "make_the_wait_a_block", "you wrote a wait in words; the journal cannot see it", "block the task so it opens by itself: journal task block <n> --on task:<m> for a task it waits on, --until '<command>' for anything else", repeat=Timeout.minutes(30))
    UNMOVED_TASKS = Nudge("workers", "blocked_work_stands_still", "these blocked or paused tasks stand still: {{tasks}}; the plan needs restructuring", "check what each waits on, unblock what has arrived, split or reorder what cannot move", repeat=Timeout.minutes(60))
    UNLINKED_TASKS = Nudge("workers", "plan_order_without_dependencies", "plan {{plan}} has {{open}} open tasks and none blocked on another; its order was likely not thought through", "which tasks depend on which? block each on the one it waits for: journal task block <n> --on task:<m>", repeat=Timeout.minutes(240))
    PRIORITIES = Nudge("workers", "reprioritise", "plan {{plan}}, phase {{phase}}: which open task unblocks the most others, or you (a permission, a missing tool, a failing check, a stalled worker)? Are the queues in that order?", "answer with journal plan priorities '<the order and why>'", repeat=Timeout.minutes(15))
    UNBLOCKER_QUEUED = Nudge("workers", "unblocking_task_waits_in_a_queue", "task {{task}} unblocks you but is number {{place}} in worker {{n}}'s queue", "put it first: journal worker queue {{n}} {{task}} --first", repeat=Timeout.seconds(0))
    MODEL_OVERPOWERED = Nudge("workers", "model_too_strong", "worker {{n}} ran on {{model}} for work a cheaper model would have done", repeat=Timeout.seconds(0))
    MODEL_UNDERPOWERED = Nudge("workers", "model_too_weak", "worker {{n}} ran on {{model}} and was sent back {{send_backs}} times: work like this needs a stronger model", repeat=Timeout.seconds(0))
    TEST_RUN_FAILED = Nudge("workers", "worker_test_run_failed", "worker {{n}}: {{failed}} failed in its test run", repeat=Timeout.seconds(0))
    WORKER_KEEPS_FAILING = Nudge("workers", "worker_keeps_failing", "worker {{n}} failed {{runs}} test runs in a row", repeat=Timeout.seconds(0))
    WORKER_STOPPED_UNREPORTED = Nudge("workers", "worker_stopped_unreported", "worker {{n}} stopped before it reported{{cause}}", repeat=Timeout.seconds(0))
    SUBAGENT_OVERFLOW = Nudge("workers", "too_many_subagents", "{{running}} subagents are running, the most at once", "wait for one, or do it yourself", repeat=Timeout.seconds(0))
    PLACES_FULL = Nudge("workers", "places_full_check_work", "places full; check worker {{n}} first", "its check frees a place", repeat=Timeout.tool_uses(30))
    WORKER_OVERFLOW = Nudge("workers", "too_many_workers", "{{out}} workers are out, the most at once", "`journal worker wait`, or send the job to one that reported", repeat=Timeout.seconds(0))
    WORKER_FILE = Nudge("workers", "file_is_the_workers", "that file is in worker {{n}}'s worktree", "`journal worker send {{n}} \"<job>\"`, or wait for its report and merge", repeat=Timeout.seconds(0))
    UNREAD_WORKER_REPORTS = Nudge("workers", "act_on_the_reports", "{{reports_waiting}} reported and you have not acted on it", "give it its next job, stop it, or mark it done", repeat=Timeout.seconds(180), blocks_regardless=True)
    WORKER_KNOWS_FILES = Nudge("workers", "send_it_to_the_worker_that_knows", "{{count}} idle workers already worked on files this job names:\n{{workers}}", "send the job to one of them, or add --fresh to the dispatch", repeat=Timeout.seconds(0))
    IDLE_CAP = Nudge("workers", "send_it_to_an_idle_worker", "{{count}} of the {{kept}} {{profile}} workers kept are idle:\n{{workers}}", "send the job to one of them, or retire one with `journal worker complete <n> --why \"<reason>\"`", repeat=Timeout.seconds(0))
    REUSE_QUESTION = Nudge("workers", "could_it_be_reused", "can worker {{n}} be reused?", "if so, `journal worker send {{n}} \"<job>\"`; if not, repeat the command with --why \"<why>\"", repeat=Timeout.seconds(0))
    SILENT_WORKER = Nudge("workers", "worker_quiet", "worker {{n}} quiet {{minutes}} min; last: {{last}}", repeat=Timeout.seconds(0))
    SPLIT_ADVICE = Nudge("workers", "worker_quiet_split", "worker {{n}} quiet {{minutes}} min; split its job?", repeat=Timeout.seconds(0))
    PROOF_REJECTED = Nudge("workers", "worker_sent_back", "worker {{n}} back on point {{point}}", repeat=Timeout.seconds(0))
    PROOF_REJECTED_REPEAT = Nudge("workers", "worker_sent_back_again", "worker {{n}} back on point {{point}} again; earlier: {{earlier}}", repeat=Timeout.seconds(0))
    PROOF_REJECTED_OFTEN = Nudge("workers", "worker_sent_back_repeatedly", "worker {{n}} back on point {{point}} {{times}} times on {{model}}; earlier: {{earlier}}", "change the target or the worker, or send its next job on a stronger model: journal worker send {{n}} --model <model> \"<job>\"", repeat=Timeout.seconds(0))
    COSTLY_SHAPED_WORK = Nudge("workers", "worker_costly_on_shaped_work", "worker {{n}} has spent ${{dollars}} on {{model}} for work its profile says is of a settled shape", "a cheaper model may do it: journal worker send {{n}} --model <model> \"<job>\"", repeat=Timeout.seconds(0))
    SUBAGENT_REUSE = Nudge("workers", "send_the_job_to_the_subagent", "{{count}} idle subagents already worked on files this job names:\n{{subagents}}", "send the job to one with its SendMessage line, or retire one with `journal subagent retire <n>`", repeat=Timeout.seconds(0))
